<template>
  <section class="hx-page tc-page">
    <div class="tc-preview"><span>交互预览 · 示例数据 · 不连接生产或真实 AI</span><div><span>体验身份</span><ElRadioGroup v-model="previewRole" size="small"><ElRadioButton value="designer">设计人员</ElRadioButton><ElRadioButton value="operator">运营人员</ElRadioButton><ElRadioButton value="super_admin">超级管理员</ElRadioButton></ElRadioGroup><ElButton text size="small" @click="resetDemo">重置预览</ElButton></div></div>
    <ElAlert v-if="storageNotice" :title="storageNotice" type="warning" :closable="false" />
    <template v-if="!route.params.id && (!management || admin)">
      <div class="hx-heading"><div><span class="hx-admin-kicker">{{ workspace ? 'DESIGN TASKS' : 'TASK CENTER' }}</span><h1>{{ workspace?.title || '任务中心' }}</h1><p>{{ workspace ? '为这项业务创建任务，再在任务内探索不同设计方案。' : '按成员和业务查看全部任务，跟进各方案的对话与执行过程。' }}</p></div><ElTag v-if="management" type="info">超级管理员 · 只读查看</ElTag><ElButton v-else type="primary" :icon="Plus" @click="openCreate">新建任务</ElButton></div>
      <div class="tc-card">
        <div class="tc-summary"><button v-for="s in statuses" :key="s.value" :class="{ selected: status === s.value }" @click="status = s.value; page = 1">{{ s.label }} <strong>{{ scopeTasks.filter(t => s.value === 'all' || (s.value === 'done' ? t.completed : !t.completed)).length }}</strong></button><span>{{ management ? '全部成员的任务 · 只读查看' : '我的任务 · 各方案独立保存' }}</span></div>
        <div class="tc-filters"><label>任务名称<ElInput v-model="search" clearable placeholder="搜索任务名称" aria-label="搜索任务名称" @input="page = 1" /></label><label v-if="!workspace">所属业务<ElSelect v-model="business" placeholder="全部业务" aria-label="所属业务筛选" @change="page = 1"><ElOption label="全部业务" value="" /><ElOption v-for="w in workspaces" :key="w.key" :label="w.title" :value="w.key" /></ElSelect></label><label v-if="management">创建人<ElSelect v-model="owner" placeholder="全部成员" aria-label="创建人筛选" @change="page = 1"><ElOption label="全部成员" value="" /><ElOption v-for="person in ['我', '示例成员 A', '示例成员 B']" :key="person" :label="person" :value="person" /></ElSelect></label><ElButton @click="clearFilters">重置筛选</ElButton></div>
        <div class="tc-list-note"><span>{{ workspace ? workspace.group + ' / ' + workspace.title : admin ? '全部成员 · 全部业务任务' : '我的设计任务' }}</span><span>共 {{ filtered.length }} 个任务</span></div>
        <ElTable :data="filtered.slice((page-1)*8,page*8)" class="tc-table" row-key="id"><ElTableColumn label="任务名称" min-width="290"><template #default="{ row }"><button class="tc-task-name" @click="enter(row)">{{ row.name }}</button><small class="tc-sub">{{ row.sessions.length }} 个方案会话 · {{ row.sessions.reduce((n: number, s: Session) => n+s.messages.filter(m => m.role==='user').length, 0) }} 轮对话</small></template></ElTableColumn><ElTableColumn label="所属业务" min-width="220"><template #default="{row}">{{ getWorkspace(row.workspace).title }}</template></ElTableColumn><ElTableColumn label="创建人" width="125"><template #default="{row}"><span class="tc-person">{{ row.owner }}</span></template></ElTableColumn><ElTableColumn label="任务状态" width="120"><template #default="{row}"><ElTag :type="row.completed ? 'success' : 'primary'" size="small">{{ row.completed ? '已完成' : '进行中' }}</ElTag></template></ElTableColumn><ElTableColumn prop="updated" label="最近更新（北京时间）" width="190" /><ElTableColumn label="操作" width="180" fixed="right"><template #default="{row}"><ElButton link type="primary" @click="enter(row)">{{ management ? '只读查看' : '进入任务' }}</ElButton><ElDropdown v-if="!management && row.owner === '我'" trigger="click" @command="(c: string) => taskAction(c, row)"><ElButton link aria-label="更多任务操作">更多</ElButton><template #dropdown><ElDropdownMenu><ElDropdownItem command="rename">重命名</ElDropdownItem><ElDropdownItem command="complete">{{ row.completed ? '重新打开' : '标记完成' }}</ElDropdownItem><ElDropdownItem command="delete" divided>删除任务</ElDropdownItem></ElDropdownMenu></template></ElDropdown></template></ElTableColumn><template #empty><div class="tc-empty"><ElIcon><FolderOpened /></ElIcon><strong>{{ search || business || owner ? '没有符合条件的任务' : '还没有设计任务' }}</strong><p>{{ management ? '暂无符合条件的任务，可调整筛选条件。' : '点击“新建任务”，为本次设计填写名称。' }}</p><ElButton v-if="!management" type="primary" @click="openCreate">新建任务</ElButton></div></template></ElTable>
        <div class="tc-pagination"><span>任务下的每个方案会话拥有独立上下文</span><ElPagination v-model:current-page="page" :total="filtered.length" :page-size="8" layout="prev, pager, next" /></div>
      </div>
    </template>
    <template v-else-if="task && (management ? admin : task.owner === '我')">
      <div class="tc-back"><ElButton :icon="ArrowLeft" @click="back">返回任务列表</ElButton><span>{{ getWorkspace(task.workspace).group }} / {{ getWorkspace(task.workspace).title }}</span><ElTag v-if="readonly" type="info">超级管理员 · 只读查看</ElTag></div>
      <div class="hx-heading tc-task-heading"><div><span class="hx-admin-kicker">DESIGN TASK</span><h1>{{ task.name }}</h1><p>创建人：{{ task.owner }} <span class="tc-separator">·</span> {{ task.sessions.length }} 个方案会话 <span class="tc-separator">·</span> 最近更新 {{ task.updated }}</p></div><div class="tc-actions"><ElTag :type="task.completed ? 'success' : 'primary'">{{ task.completed ? '已完成' : '进行中' }}</ElTag><template v-if="!readonly"><ElButton @click="taskAction('complete',task)">{{ task.completed ? '重新打开任务' : '标记任务完成' }}</ElButton><ElButton type="primary" :icon="Plus" :disabled="task.completed" @click="newSession">新建方案会话</ElButton></template></div></div>
      <div class="tc-workbench"><header class="tc-toolbar"><div><ElIcon><MagicStick /></ElIcon><strong>AI 设计工作台</strong><small>{{ task.completed ? '任务已完成' : '各方案独立对话' }}</small></div><ElButton size="small" :icon="ChatDotRound" @click="showSessions = !showSessions">方案会话 · {{ task.sessions.length }}</ElButton></header>
        <div class="tc-workbody"><aside v-if="showSessions" class="tc-sessions"><div class="tc-panel-heading"><strong>当前任务的方案</strong><span>{{ task.sessions.length }}</span></div><p>在不同会话里探索不同方案</p><div v-for="s in task.sessions" :key="s.id" class="tc-session-row" :class="{active:s.id===activeSessionId}"><button class="tc-session" @click="chooseSession(s.id)"><strong>{{ s.name }}</strong><small>{{ s.messages.filter(m=>m.role==='user').length ? s.messages.filter(m=>m.role==='user').length + ' 轮对话' : '尚未开始对话' }}</small></button><ElDropdown v-if="!readonly && !task.completed" trigger="click" @command="(c: string)=>sessionAction(c,s)"><ElButton text aria-label="方案会话操作">···</ElButton><template #dropdown><ElDropdownMenu><ElDropdownItem command="rename">重命名</ElDropdownItem><ElDropdownItem command="delete">删除会话</ElDropdownItem></ElDropdownMenu></template></ElDropdown></div><ElButton v-if="!readonly" class="tc-add-session" :icon="Plus" :disabled="task.completed" @click="newSession">新建方案会话</ElButton><div class="tc-sidebar-note">会话仅属于当前任务。<br>切换方案保留各自的内容和草稿。</div></aside>
        <section v-if="session" class="tc-chat"><header class="tc-chat-heading"><strong>{{ session.name }}</strong><small>{{ readonly ? '以管理员身份只读查看' : '独立会话 · 切换会保留附件和草稿' }}</small></header><div ref="messagesEl" class="tc-messages" aria-live="polite"><div v-if="!session.messages.length" class="tc-conversation-empty"><ElIcon><ChatDotRound /></ElIcon><strong>{{ readonly ? '该方案尚未提交消息' : '从这个方案的第一条要求开始' }}</strong><p>{{ readonly ? '成员提交消息后，可在这里查看对话和结果。' : '上传素材，描述想法。对话和结果都会保存在当前方案中。' }}</p></div><article v-for="m in session.messages" :key="m.id" class="tc-message" :class="m.role"><div class="tc-message-meta">{{ m.role==='user' ? task.owner==='我' ? '我' : task.owner : 'Codex' }}<time>{{ m.time }}</time></div><ElTag v-if="m.skill" class="tc-message-skill" size="small">{{ m.skill }}</ElTag><div class="tc-bubble">{{ m.text }}<div v-if="m.files?.length" class="tc-files"><ElTag v-for="f in m.files" :key="f" type="info">{{ f }}</ElTag></div></div></article></div>
        <template v-if="!readonly && !task.completed"><div class="tc-composer"><div class="tc-files" v-if="session.files.length"><ElTag v-for="(f,i) in session.files" :key="i" closable @close="session.files.splice(i,1)">{{ f }}</ElTag></div><ElInput v-model="session.draft" type="textarea" :rows="3" resize="none" aria-label="设计要求" placeholder="描述你的要求，或继续提出修改意见…" @keydown.enter.exact="sendKey" /><div class="tc-compose-tools"><div><ElCheckbox v-model="session.skill">{{ getWorkspace(task.workspace).title }} Skill · 本轮使用</ElCheckbox><ElButton text :icon="Paperclip" @click="fileInput?.click()">上传附件</ElButton></div><ElButton type="primary" :icon="Promotion" :disabled="!session.draft.trim() && !session.files.length" @click="send">发送</ElButton></div><input ref="fileInput" type="file" hidden multiple @change="attach" /></div><div class="tc-footnote">发送到：{{ session.name }} · Enter 发送，Shift + Enter 换行</div></template><div v-else class="tc-readonly">{{ readonly ? '管理员只读查看 · 无法代发消息或修改用户内容' : '任务已完成 · 重新打开任务后可继续设计' }}</div></section>
        <div v-else class="tc-empty tc-chat"><ElIcon><ChatDotRound /></ElIcon><strong>{{ readonly ? '该任务尚未创建方案会话' : '为这个任务创建第一个方案' }}</strong><p>{{ readonly ? '成员创建方案后，可在这里查看。' : '每个方案使用独立会话，可以持续讨论与修改。' }}</p><ElButton v-if="!readonly" type="primary" :disabled="task.completed" @click="newSession">新建方案会话</ElButton></div>
        </div>
      </div>
    </template>
    <div v-else class="tc-card tc-empty"><strong>任务不存在或当前身份无权查看</strong><ElButton @click="back">返回任务列表</ElButton></div>
    <ElDialog v-model="creating" title="新建任务" width="min(520px,94vw)" :close-on-click-modal="false" @opened="nameInput?.focus()"><p class="tc-dialog-intro">先为本次设计命名，再在任务内创建不同方案的会话。</p><ElForm label-position="top" @submit.prevent="createTask"><ElFormItem label="所属业务" required><ElSelect v-model="newBusiness" :disabled="!!workspace" aria-label="新任务所属业务"><ElOption v-for="w in workspaces" :key="w.key" :value="w.key" :label="w.group+' / '+w.title" /></ElSelect><small class="tc-sub">{{ workspace ? '已根据当前菜单绑定业务。' : '创建后，任务内的所有方案都使用这项业务。' }}</small></ElFormItem><ElFormItem label="任务名称" required :error="formError"><ElInput ref="nameInput" v-model="newName" maxlength="60" show-word-limit placeholder="例如：iPhone 17 透明手机壳新品主图" aria-label="任务名称" @input="formError=''" @keydown.enter.prevent="createTask" /></ElFormItem><div class="tc-create-note"><ElIcon><ChatDotRound /></ElIcon><span>创建后进入任务工作台，可新建多个方案会话。</span></div></ElForm><template #footer><ElButton @click="creating=false">取消</ElButton><ElButton type="primary" @click="createTask">创建并进入</ElButton></template></ElDialog>
  </section>
</template>
<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox, type InputInstance } from 'element-plus'
import { Plus, ArrowLeft, MagicStick, ChatDotRound, Paperclip, Promotion, FolderOpened } from '@element-plus/icons-vue'
import { domesticWorkspaces as workspaces } from '@/api/hengxin/domestic-workspaces'
import { tasks, admin, previewRole, storageNotice, reset, makeSession, stamp, uid, type Task, type Session } from './state'
const route=useRoute(), router=useRouter()
const workspace=computed(()=>workspaces.find(w=>w.path===route.path))
const management=computed(()=>route.path.startsWith('/management/task-center'))
const task=computed(()=>tasks.find(t=>t.id===route.params.id))
const readonly=computed(()=>management.value || (!!task.value && task.value.owner!=='我'))
const viewedSessionId=ref('')
const activeSessionId=computed(()=>readonly.value && task.value?.sessions.some(s=>s.id===viewedSessionId.value) ? viewedSessionId.value : task.value?.active)
const session=computed(()=>task.value?.sessions.find(s=>s.id===activeSessionId.value))
watch(()=>task.value?.id,()=>{viewedSessionId.value=''})
function chooseSession(id:string){if(readonly.value)viewedSessionId.value=id;else if(task.value)task.value.active=id}
const search=ref(''), business=ref(''), owner=ref(''), status=ref('all'), page=ref(1), showSessions=ref(true)
const statuses=[{value:'all',label:'全部任务'},{value:'active',label:'进行中'},{value:'done',label:'已完成'}]
const scopeTasks=computed(()=>tasks.filter(t=>(management.value && admin.value || t.owner==='我') && (!workspace.value || t.workspace===workspace.value.key)))
const filtered=computed(()=>scopeTasks.value.filter(t=>(!search.value || t.name.toLowerCase().includes(search.value.toLowerCase())) && (!business.value || t.workspace===business.value) && (!management.value || !owner.value || t.owner===owner.value) && (status.value==='all' || (status.value==='done' ? t.completed : !t.completed))).sort((a,b)=>b.updated.localeCompare(a.updated)))
const creating=ref(false),newName=ref(''),newBusiness=ref(''),formError=ref(''),nameInput=ref<InputInstance>(),fileInput=ref<HTMLInputElement>(),messagesEl=ref<HTMLElement>()
const returnPath=computed(()=>management.value && admin.value ? '/management/task-center' : typeof route.query.from==='string' && workspaces.some(w=>w.path===route.query.from) ? route.query.from : getWorkspace(task.value?.workspace || 'camera').path)
function getWorkspace(key:string){return workspaces.find(w=>w.key===key) || workspaces[0]}
function clearFilters(){search.value='';business.value='';owner.value='';status.value='all';page.value=1}
watch(()=>route.path,()=>{if(!route.params.id)clearFilters();creating.value=false})
watch(admin,()=>{page.value=1})
function openCreate(){if(!workspace.value || management.value)return;newName.value='';newBusiness.value=workspace.value?.key || '';formError.value='';creating.value=true}
function createTask(){if(!workspace.value || management.value)return;newBusiness.value=workspace.value.key;if(!newBusiness.value){ElMessage.warning('请选择所属业务');return}if(!newName.value.trim()){formError.value='请填写任务名称';return}const t:Task={id:uid(),name:newName.value.trim(),workspace:newBusiness.value,owner:'我',completed:false,updated:stamp(),sessions:[],active:''};tasks.unshift(t);creating.value=false;enter(t);ElMessage.success('任务已创建，可以开始添加方案会话')}
function enter(t:Task){void router.push({path:(management.value ? '/management/task-center/' : '/tasks/')+t.id,query:{from:route.path}})}
function back(){void router.push(returnPath.value)}
async function nameDialog(title:string,value=''){try{const answer=await ElMessageBox.prompt('使用清晰的名称，方便区分不同设计方案。',title,{inputValue:value,inputPlaceholder:'例如：方案一 · 简约白底',inputValidator:v=>!!v?.trim() && v.trim().length<=60 || '请输入1至60个字符',confirmButtonText:'确定',cancelButtonText:'取消'});return answer.value.trim()}catch{return undefined}}
async function newSession(){const t=task.value;if(!t||readonly.value||t.completed)return;const name=await nameDialog('新建方案会话',`方案${t.sessions.length+1}`);if(!name)return;const s=makeSession(name);t.sessions.push(s);t.active=s.id;t.updated=stamp();showSessions.value=true}
async function sessionAction(c:string,s:Session){const t=task.value;if(!t||readonly.value||t.completed)return;if(c==='rename'){const name=await nameDialog('重命名会话',s.name);if(name)s.name=name}else{try{await ElMessageBox.confirm(`删除“${s.name}”及其预览对话？其他方案不受影响。`,'删除方案会话',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});t.sessions=t.sessions.filter(x=>x.id!==s.id);if(t.active===s.id)t.active=t.sessions[0]?.id||''}catch{return}}t.updated=stamp()}
async function taskAction(c:string,t:Task){if(management.value || t.owner!=='我')return;if(c==='complete'){t.completed=!t.completed;t.updated=stamp();ElMessage.success(t.completed?'任务已标记完成':'任务已重新打开');return}if(c==='rename'){const name=await nameDialog('重命名任务',t.name);if(name)t.name=name;return}try{await ElMessageBox.confirm(`删除“${t.name}”及其 ${t.sessions.length} 个方案会话？仅影响本地预览数据。`,'删除任务',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});tasks.splice(tasks.indexOf(t),1)}catch{/* cancelled */}}
function sendKey(e:Event|KeyboardEvent){if('isComposing' in e && e.isComposing)return;e.preventDefault();send()}
function send(){const s=session.value,t=task.value;if(!s||!t||readonly.value||t.completed||(!s.draft.trim()&&!s.files.length))return;s.messages.push({id:uid(),role:'user',text:s.draft.trim(),time:stamp(),skill:s.skill ? getWorkspace(t.workspace).title+' Skill（预览）' : undefined,files:[...s.files]});s.draft='';s.files=[];s.skill=false;s.messages.push({id:uid(),role:'assistant',text:`已在“${s.name}”中收到你的要求。你可以继续补充意见，或新建另一个会话探索不同方案。\n\n【预览演示】此回复仅用于体验交互，不调用真实 AI，也不会生成图片。`,time:stamp()});t.updated=stamp();void nextTick(()=>messagesEl.value?.scrollTo({top:messagesEl.value.scrollHeight,behavior:'smooth'}))}
function attach(e:Event){const input=e.target as HTMLInputElement;if(session.value&&!readonly.value&&!task.value?.completed){session.value.files.push(...Array.from(input.files||[]).map(f=>f.name));ElMessage.info('附件名称已加入当前方案；预览不会上传文件。')}input.value=''}
async function resetDemo(){try{await ElMessageBox.confirm('清空本地预览中新增的任务与对话，恢复示例数据？','重置预览',{confirmButtonText:'重置',cancelButtonText:'取消'});reset();clearFilters();void router.push(admin.value ? '/management/task-center' : workspaces[0].path)}catch{/* cancelled */}}
</script>
